## This file cleans up all of the .output folders that were generated by default in
## prior versions of Gambit. This was mainly for debugging, and is no longer 
## desirable by default. To turn it on, add a -v or -verbose switch to your
## reload commands. 
##
## For example: gbt r -a ambu/dragon/war -v
##

$root = (Resolve-Path -LiteralPath (Join-Path $PSScriptRoot 'settings')).Path.TrimEnd('\')
$prefix = $root + '\'

$folders = Get-ChildItem -LiteralPath $root -Directory -Force -Recurse -Filter '.output' |
Where-Object { $_.FullName.StartsWith($prefix, [StringComparison]::OrdinalIgnoreCase) } |
Sort-Object { $_.FullName.Length } -Descending

$folders | ForEach-Object {
    # Shows you what would be deleted, but doesn't actually delete anything
    Remove-Item -LiteralPath $_.FullName -Recurse -Force -WhatIf

    # Actually deletes the results
    # Remove-Item -LiteralPath $_.FullName -Recurse -Force
}